let LANG = 'en';
try { LANG = localStorage.getItem('asl-lang') || 'en'; } catch (e) {}

function t(key) {
  return (STRINGS[LANG] && STRINGS[LANG][key]) || STRINGS.en[key] || key;
}

function setLang(lang) {
  LANG = lang;
  try { localStorage.setItem('asl-lang', lang); } catch (e) {}
  document.documentElement.lang = lang;
}

function fmtDate(iso, opts = { weekday: 'short', month: 'short', day: 'numeric' }) {
  const [y, m, d] = iso.split('-').map(Number);
  const s = new Date(y, m - 1, d).toLocaleDateString(LANG === 'es' ? 'es-US' : 'en-US', opts);
  return s.charAt(0).toUpperCase() + s.slice(1);
}
